exec("import shutil,subprocess,sys,tempfile,unittest\nfrom pathlib import Path\n\nclass TestValidator(unittest.TestCase):\n def base(self):\n  root=Path(tempfile.mkdtemp()); self.addCleanup(shutil.rmtree,root)\n  for name in ['00_meta','10_knowledge','20_projects','50_memory']: (root/name).mkdir(parents=True)\n  (root/'00_meta'/'paios.yaml').write_text('name: test'+chr(10),encoding='utf-8')\n  (root/'00_meta'/'principles.md').write_text(('---|id: doc-principles|type: meta|title: Principles|created: 2026-01-01|---|').replace('|',chr(10)),encoding='utf-8')\n  return root\n def run_validator(self,root): return subprocess.run([sys.executable,'tools/validate_paios.py',str(root)],capture_output=True,text=True)\n def write(self,path,identifier,kind='knowledge',created='2026-01-02',extra=''):\n  path.write_text(('---|id: '+identifier+'|type: '+kind+'|title: Example|created: '+created+'|'+extra+'---|').replace('|',chr(10)),encoding='utf-8')\n def test_valid_entry_passes(self):\n  root=self.base(); self.write(root/'10_knowledge'/'k-2026-0001.md','k-2026-0001'); result=self.run_validator(root)\n  self.assertEqual(result.returncode,0,result.stdout+result.stderr)\n def test_duplicate_and_wrong_prefix_fail(self):\n  root=self.base(); self.write(root/'20_projects'/'a.md','k-2026-0001','project',extra='status: active|'); self.write(root/'20_projects'/'b.md','k-2026-0001','project',extra='status: active|'); result=self.run_validator(root)\n  self.assertNotEqual(result.returncode,0); self.assertIn('doppelte ID',result.stdout)\n def test_invalid_date_fails(self):\n  root=self.base(); self.write(root/'10_knowledge'/'bad.md','k-2026-0002',created='2026-99-99'); result=self.run_validator(root)\n  self.assertNotEqual(result.returncode,0); self.assertIn('created',result.stdout)\n\nif __name__=='__main__': unittest.main()")
